import type {Task} from '../types';
// Reviewed lesson by lesson; examples differ from the independent task.
export const GRADE3_TEACHING:Record<string,Partial<NonNullable<Task['lesson']>>>={
 g3_m1_l1:{
 explanation:'Представь, что ты нарисовал открытку и хочешь открыть её завтра. Сохранённый рисунок становится файлом. У файла есть имя: оно помогает человеку найти свою работу. В конце имени часто стоит точка и расширение — например, .jpg. Расширение сообщает формат файла: картинка это, звук или текст, и помогает выбрать программу для открытия. Переименовать картинку в .mp3 — не значит превратить её в музыку: содержимое останется прежним.',
 example:'Сравним два файла: каникулы.jpg и каникулы.mp3. Имена до точки одинаковые, но окончания разные. Первый файл — изображение, второй — звук. Значит, когда выбираем программу, смотрим не только на название, но и на расширение.',
 goal:'Прочитай вопрос о файле, выбери один ответ и нажми «Проверить».',steps:['Найди в имени точку и окончание после неё.','Подумай, что сообщает имя, а что — расширение.','Выбери ответ. Если ошибся, прочитай разбор и попробуй ещё раз.'],success:'Ты различаешь название работы и её формат.'},
 g3_m1_l2:{
 explanation:'В одной папке лежат рисунки, песни и тексты — нужный файл трудно найти. Разделим их по назначению: изображения отдельно, музыку отдельно, документы отдельно. Сначала прочитай окончание имени: .jpg и .png обычно обозначают картинки, .mp3 и .wav — звук, .txt и .docx — текст. Программы с расширениями .exe и .bat могут выполнять команды. Это не обязательно вирусы, но незнакомую программу нельзя запускать без проверки взрослым. В нашем задании подозрительные программы откладываем в «Карантин».',
 example:'В другом проекте есть море.jpg, шум.wav и заметка.txt. По окончаниям выбираем папки «Рисунки», «Музыка» и «Документы». Незнакомый подарок.exe сначала откладываем для проверки, даже если название обещает что-то приятное.',
 goal:'Разложи все посылки по четырём папкам: нажми на файл, затем на подходящую папку. Можно и перетаскивать.',steps:['Прочитай расширение файла и реши, что он хранит.','Нажми на файл, затем на папку. Счётчик покажет доставленную посылку.','Повтори для остальных файлов. Если выбор неверный, прочитай сообщение и выбери другую папку.'],success:'Счётчик показывает, что все файлы доставлены в подходящие папки.'},
 g3_m1_l3:{
 explanation:'Папка помогает собрать связанные файлы. Если их много, внутри неё можно создать ещё одну папку — подпапку. Например, все школьные работы лежат в «Школа», а рисунки — внутри «Рисунки». Чтобы добраться до файла, открываем папки по порядку. Такой маршрут называют путём. Файл и папка отличаются: файл хранит саму работу, папка помогает её организовать.',
 example:'Путь «Дом → Праздник → открытка.png» читаем так: открываем «Дом», затем «Праздник», потом рисунок открытка.png. «Праздник» находится внутри другой папки, поэтому это подпапка.',goal:'Рассмотри устройство папок в вопросе и выбери подходящее название.',steps:['Определи, что находится внутри чего.','Сравни варианты: папка, подпапка, файл и ярлык — разные вещи.','Нажми «Проверить» и прочитай объяснение результата.'],success:'Ты можешь объяснить, почему папка называется вложенной.'},
 g3_m1_l4:{
 explanation:'Чтобы печатать, нажми в область текста и пользуйся клавиатурой компьютера. Экранная клавиатура только показывает, где находится следующая буква. В русском домашнем ряду стоят ФЫВА и ОЛДЖ: пальцам удобно возвращаться к этим клавишам. Сначала важна точность, а не скорость. Напечатанная буква должна совпасть с образцом; если заметил ошибку, удали её клавишей Backspace и введи правильную. Не добавляй лишние пробелы.',
 example:'Потренируем порядок на другом коротком образце «фва». Сначала ищем ф, затем в, затем а. Если получилось «фба», стираем ошибочную часть и печатаем её заново. Сравниваем буквы по порядку, а не только длину строки.',goal:'Напечатай показанный образец на клавиатуре компьютера. Буквы, пробелы и регистр должны совпасть.',steps:['Нажми в текстовую область, чтобы появился курсор.','Печатай по одной букве, сверяясь с подсветкой и образцом.','Исправляй ошибки Backspace. Когда весь текст совпадёт, задание завершится автоматически.'],success:'Весь введённый текст совпадает с образцом, появилась отметка выполнения.'},
 g3_m1_l5:{concept:"Печатаем сообщение: Shift, пробелы и знаки",
 explanation:'Теперь будем печатать сообщение целиком. Слова разделяются пробелом: нажимай его один раз между словами, если так показано в образце. Для большой буквы удерживай Shift и нажми нужную букву, затем отпусти Shift. Знаки препинания тоже часть сообщения — запятую или точку нельзя пропускать. Следи за языком клавиатуры компьютера: русские и английские буквы могут выглядеть похоже, но это разные символы. При ошибке вернись Backspace и исправь текст.',
 example:'В другом образце «Привет, друг!» первая буква большая, после запятой один пробел, в конце восклицательный знак. «привет друг» — другой текст: здесь пропущены большая буква и знаки.',goal:'Напечатай весь образец, сохранив большие буквы, пробелы и знаки.',steps:['Включи нужный язык на клавиатуре компьютера и нажми в область ввода.','Печатай небольшими частями: слово, знак, пробел, следующее слово.','Исправь несовпадения. Задание завершится, когда текст совпадёт полностью.'],success:'Сообщение совпало с образцом целиком.'},
 g3_m1_l6:{
 explanation:'На рабочем столе бывают файлы и ярлыки. Ярлык — указатель, который помогает быстро открыть работу или программу. Удалить указатель и удалить саму работу — разные действия. Это похоже на закладку в книге: если убрать закладку, книга не исчезнет. Перед удалением файла проверь, нужна ли работа и есть ли копия. Обычный удалённый файл часто попадает в Корзину, но не каждое удаление можно отменить.',
 example:'У Маши есть рисунок в папке и ярлык этого рисунка на рабочем столе. Если удалить только ярлык, рисунок останется в папке. Если удалить сам рисунок, ярлык больше не сможет его открыть.',goal:'Прочитай ситуацию об удалении и выбери, что произойдёт.',steps:['Уточни, что удаляют: сам файл или указатель на него.','Представь, где находится исходная работа после действия.','Выбери вариант и проверь рассуждение по разбору.'],success:'Ты различаешь удаление ярлыка и удаление исходного файла.'},
 g3_m1_l7:{
 explanation:'Применим то, что узнали о файлах. Название до точки помогает человеку понять тему работы. Окончание после точки помогает узнать формат: .txt и .docx обычно используют для текста, .jpg и .png — для изображений, .mp3 — для звука. Слова в названии могут запутать: файл «музыка.txt» остаётся текстовым файлом. Поэтому сначала отдели имя от расширения, затем сравни расширение с известными форматами.',
 example:'Есть рецепт.png и рецепт.txt. Первый может хранить фотографию рецепта, второй — текст, который можно читать и менять в текстовом редакторе. Одинаковая тема не означает одинаковый формат.',goal:'Определи вид файла из вопроса по его расширению и проверь ответ.',steps:['Найди окончание имени после точки.','Вспомни, какой вид работы обычно хранит этот формат.','Выбери ответ и объясни себе, почему остальные виды не подходят.'],success:'Ты определяешь формат по расширению, а не угадываешь по названию.'},
 g3_m2_l1:{
 explanation:'Когда ты нажимаешь кнопку в программе, компьютер должен выполнить команды. За вычисления и сравнения отвечает процессор. Например, он складывает числа и проверяет, одинаковы ли два значения. Процессор не угадывает желание человека: программа задаёт, что сделать. Другие детали помогают ему: память держит нужные данные, накопитель хранит сохранённые файлы, экран показывает результат. Поэтому важно различать работу детали, а не только помнить её название.',
 example:'Калькулятор получил команду сложить 7 и 2. Процессор выполняет вычисление. Экран показывает ответ, а клавиатура помогает ввести числа. Это три разные роли в одной задаче.',
 goal:'Выбери деталь, которая выполняет команды и вычисления.',steps:['Прочитай, какую работу описывает вопрос.','Отдели вычисление от ввода, показа и хранения.','Выбери ответ и нажми «Проверить».'],success:'Ты объясняешь выбор через работу процессора.'},
 g3_m2_l2:{
 explanation:'У компьютера есть память для текущей работы и место для долгого хранения. Оперативная память, или ОЗУ, временно держит данные открытых программ. Представь стол, на котором сейчас разложены листы. Накопитель похож на шкаф: туда записываются сохранённые файлы. Когда питание выключается, данные в обычной ОЗУ теряются. Поэтому перед завершением работы нажимай «Сохранить»: программа записывает файл на накопитель. Автосохранение есть не везде, рассчитывать на него без проверки нельзя.',
 example:'Лена напечатала рассказ и сохранила его. Потом добавила ещё одну строку, но не сохранила изменения. После внезапного выключения сохранённая версия остаётся на накопителе; новая строка может потеряться. Открытая работа и сохранённый файл — не одно и то же.',
 goal:'Определи, что произойдёт с данными в оперативной памяти при выключении питания.',steps:['Уточни, о какой памяти говорится: ОЗУ или накопитель.','Вспомни, нужна ли ей электроэнергия для хранения текущих данных.','Выбери ответ и прочитай разбор.'],success:'Ты различаешь временные данные и сохранённый файл.'},
 g3_m2_l3:{
 explanation:'Информация может идти в компьютер или из компьютера к человеку. Ввод — когда мы сообщаем компьютеру данные: нажимаем клавишу, говорим в микрофон или двигаем мышь. Вывод — когда компьютер показывает или воспроизводит результат: экран показывает картинку, колонки издают звук, принтер печатает лист. Не путай направление с размером устройства. Некоторые устройства совмещают обе роли: сенсорный экран и показывает изображение, и принимает касания.',
 example:'В игре человек нажал стрелку на клавиатуре — это ввод. Персонаж передвинулся на мониторе — это вывод. Звук шага из колонок тоже вывод: результат идёт от компьютера к человеку.',
 goal:'Найди среди вариантов устройство, которое выдаёт человеку результат работы компьютера.',steps:['Представь, как используется каждое устройство.','Спроси себя: данные идут в компьютер или к человеку?','Выбери устройство вывода и нажми «Проверить».'],success:'Ты называешь направление передачи информации, а не угадываешь устройство.'},
 g3_m2_l4:{
 explanation:'Бит — единица данных, у которой только два возможных значения: 0 или 1. Для знакомства представим переключатель лампы: выключено обозначим 0, включено — 1. Это наша модель; внутри настоящего компьютера данные хранятся не обязательно лампочками. Одного бита хватает для выбора между двумя состояниями, например «да» и «нет». Значение 1 не всегда означает «хорошо»: смысл обозначений задаёт правило. Сначала прочитай правило, затем определи значение.',
 example:'В модели двери договорились: 0 — закрыта, 1 — открыта. Если дверь открыли, записываем 1. Для другого устройства можно выбрать другое значение состояний; сами цифры не объясняют смысл без договорённости.',
 goal:'По правилу из вопроса выбери цифру для включённой лампочки.',steps:['Найди, как в модели обозначены два состояния.','Определи, о включённом или выключенном состоянии спрашивают.','Выбери одно значение и проверь ответ.'],success:'Ты различаешь два значения бита и понимаешь правило обозначения.'},
 g3_m2_l5:{
 explanation:'Несколько битов помогают записывать числа. В этом тренажёре у четырёх ламп разные веса: слева направо 8, 4, 2 и 1. Выключенная лампа добавляет 0, включённая — свой вес. Поэтому считаем сумму весов включённых ламп, а не количество горящих ламп. Чтобы собрать число, выбери самый большой вес, который не превышает цель, и подумай, сколько ещё не хватает. Лишнюю лампу можно выключить повторным нажатием. Смотри на текущую сумму после каждого изменения.',
 example:'На другом примере соберём 6. Вес 8 слишком велик, поэтому оставляем его выключенным. Берём 4: до 6 не хватает 2. Включаем 2, вес 1 не нужен. Проверяем: 4 + 2 = 6; включены две лампы, но число равно шести.',
 goal:'Собери число «Цель» из весов ламп. Нажимай лампы и сравнивай текущую сумму с целью.',steps:['Посмотри на число цели и подписи весов над лампами.','Включай подходящие веса. Повторное нажатие выключает лампу и убирает её вес из суммы.','При совпадении суммы раунд сменится автоматически. Повтори для всех раундов до сообщения о завершении.'],success:'Во всех раундах сумма включённых весов совпала с целью.'},
 g3_m2_l6:{
 explanation:'Один бит хранит одно значение — 0 или 1. Восемь битов объединяют в группу, которую называют байтом. Представь упаковки: в каждой ровно восемь одинаковых предметов. Чтобы посчитать биты в нескольких байтах, число байтов умножаем на 8. Если байтов стало больше, битов тоже стало больше. Не складывай число байтов с числом битов: это разные единицы, как упаковки и предметы внутри них.',
 example:'В трёх байтах три группы по восемь бит: 8 + 8 + 8 = 24. Можно записать короче: 3 × 8 = 24 бита. Число 3 описывает количество групп, число 24 — количество битов.',
 goal:'Посчитай, сколько битов содержится в указанном количестве байтов.',steps:['Прочитай, сколько байтов дано.','Для каждого байта учти 8 бит: сложи группы или умножь на 8.','Найди свой результат среди вариантов и проверь ответ.'],success:'Ты переводишь байты в биты и называешь единицу результата.'},
 g3_m2_l7:{
 explanation:'Самое большое число получится, если включить все лампы: тогда ни один вес не пропущен. Чтобы найти это число, сложи веса всех разрядов. Начинай с правого: его вес 1, следующий слева — 2, затем 4; каждый следующий вес вдвое больше. Не путай двоичную запись и обычное число: несколько единиц подряд означают включённые разряды, а не количество ламп. Если хотя бы одну лампу выключить, сумма уменьшится на её вес.',
 example:'У набора из трёх ламп веса 4, 2 и 1. При записи 111 все лампы включены: 4 + 2 + 1 = 7. Выключим среднюю лампу — получим 101 и сумму 4 + 1 = 5. Значит, максимум был при всех включённых весах.',
 goal:'Найди самое большое число для указанного набора двоичных разрядов.',steps:['Уточни число разрядов в вопросе.','Запиши их веса, удваивая от 1 справа налево.','Сложи все веса и выбери результат.'],success:'Ты находишь максимум через сумму весов, а не через число ламп.'},
 g3_m7_l3:{
 explanation:'Изображение на экране состоит из маленьких цветных точек — пикселей. Если сильно увеличить картинку, можно заметить эти точки или квадратики. Каждый пиксель находится на своём месте и имеет цвет. Много пикселей вместе образуют рисунок, как клеточки мозаики. Если точек мало, мелкие детали передать трудно. Увеличение готовой картинки не добавляет настоящих деталей: уже существующие точки просто становятся крупнее.',
 example:'Представь маленькую мозаику: красные клеточки образуют цветок, зелёные — стебель. Отдельная клеточка похожа на пиксель. Если заменить её цвет, изменится часть рисунка, а если увеличить всю мозаику, клеточки станут заметнее.',
 goal:'Выбери, в каком виде компьютер хранит растровую фотографию.',steps:['Представь картинку при сильном увеличении.','Отличи элемент изображения от детали компьютера или единицы памяти.','Выбери ответ и прочитай разбор.'],success:'Ты объясняешь, как отдельные цветные точки образуют изображение.'},
 g3_m3_l1:{concept:"Составляем первый алгоритм робота",
 explanation:'Алгоритм — понятный порядок действий для решения задачи. Исполнитель выполняет команды по очереди, а не догадывается о цели. В нашем задании исполнитель — робот на клетчатой карте. Команда forward() перемещает его на одну клетку туда, куда смотрит стрелка. right() и left() только поворачивают его: клетка при повороте не меняется. Перед запуском найди старт, цель и направление стрелки. Записывай одну команду на каждой новой строке.',
 example:'На другой карте робот смотрит вниз. Программа forward(), затем left(), затем forward() делает шаг вниз, поворот налево и шаг вправо. После поворота меняется направление следующего шага. Мы называем действия по порядку и следим за состоянием робота после каждого.',
 goal:'Составь маршрут от старта до цели командами робота и нажми «Запустить».',steps:['Открой карту результата: найди робота, стрелку, цель и препятствия.','Во вкладке кода запиши команды по одной на строке. На ноутбуке код и карта могут быть рядом.','Запусти маршрут. Если робот остановился раньше цели, исправь первый неверный шаг и запусти снова.'],success:'Робот дошёл до отмеченной цели без столкновения.'},
 g3_m3_l2:{concept:"Поворот и шаг — разные действия",
 explanation:'Поворот робота отличается от движения вправо по экрану. Команда right() поворачивает робота направо относительно того, куда он сейчас смотрит, и не делает шаг. Если стрелка смотрит вверх, после right() она посмотрит вправо. Если стрелка смотрит вправо, после right() она посмотрит вниз. left() поворачивает в противоположную сторону. Чтобы после поворота переместиться, нужна отдельная команда forward(). Проверяй стрелку перед каждым шагом.',
 example:'Робот стоит на месте и смотрит вниз. После left() он всё ещё в той же клетке, но смотрит вправо. Только следующий forward() переносит его в соседнюю клетку справа. Две команды выполняют две разные работы.',
 goal:'Доведи робота до цели, выбирая повороты по направлению его стрелки.',steps:['Посмотри, куда робот смотрит сейчас.','Поставь поворот перед шагом, если нужно изменить направление.','Запусти код и проверь, куда направлена стрелка после каждого поворота.'],success:'Все повороты направили робота в нужную сторону, маршрут достиг цели.'},
 g3_m3_l3:{concept:"Планируем путь по участкам",
 explanation:'Длинный маршрут проще планировать небольшими участками. Сначала найди свободный прямой участок до поворота и посчитай шаги. Затем реши, куда робот должен смотреть дальше. Шагом считаем переход в соседнюю клетку: стартовую клетку не прибавляем к числу шагов. Поворот меняет стрелку, но не добавляет пройденную клетку. После каждого участка мысленно поставь робота в новое место и продолжай план.',
 example:'На другой карте между роботом и углом два перехода по клеткам. Пишем два forward(), затем поворот. После поворота заново проверяем стрелку и считаем следующий участок. Так не смешиваем длины разных частей пути.',
 goal:'Разбей путь до цели на прямые участки и запиши команды для каждого.',steps:['Найди свободный путь на карте и места поворотов.','Посчитай переходы по клеткам отдельно для каждого участка.','Запусти команды и исправляй первый участок, где движение не совпало с планом.'],success:'Каждый участок маршрута выполнен по плану, робот находится на цели.'},
 g3_m3_l4:{concept:"Повторяем шаги циклом",
 explanation:'Когда одно действие повторяется, его можно записать короче с помощью цикла. В Python запись for i in range(2): означает два повторения. На следующей строке пишем повторяемую команду с четырьмя пробелами перед ней: это тело цикла. Команда без этих пробелов после цикла выполняется один раз. Двоеточие и отступ нужны программе, чтобы отличить повторение от следующего действия. Число повторов выбираем по карте, а не копируем из примера.',
 example:'На другой карте надо сделать два одинаковых шага и один поворот. Запись:\nfor i in range(2):\n    forward()\nleft()\nВ цикле повторяется только forward(). Поворот left() стоит без отступа и выполнится один раз после двух шагов.',
 goal:'Доведи робота до цели: повторяющиеся шаги можно записать циклом for.',steps:['Посчитай одинаковые шаги на свободном прямом участке.','Замени их циклом с нужным числом повторов; forward() помести на строку с отступом.','Запусти программу. Проверь число шагов, двоеточие и отступ, если результат не совпал.'],success:'Робот дошёл до цели; ты можешь объяснить, какая команда повторялась.'},
 g3_m3_l5:{
 explanation:'Программа может выполнить команды и всё равно получить не тот результат, который мы ожидали. Так бывает, если перепутали порядок, выбрали неверный поворот или забыли действие. Поиск и исправление таких ошибок называется отладкой. Сначала сравниваем план с тем, что произошло, и ищем первое отличие. Затем меняем причину и запускаем проверку снова. Если менять много команд сразу, труднее понять, что помогло.',
 example:'Робот должен был повернуть и пройти клетку, но сначала сделал шаг. Находим первое отличие: шаг произошёл до поворота. Меняем порядок этих команд и проверяем снова. Мы исправили причину, а не просто нажали запуск ещё раз.',
 goal:'Выбери название процесса, в котором находят и исправляют ошибки программы.',steps:['Вспомни последовательность: сравнить ожидание, найти ошибку, исправить, проверить.','Отличи исправление программы от обычного запуска.','Выбери ответ и нажми «Проверить».'],success:'Ты понимаешь, что отладка включает поиск причины и повторную проверку.'},
 g3_m3_l6:{
 explanation:'Иногда действие нужно выполнять не всегда, а только при определённом условии. Условие — вопрос, на который программа получает «да» или «нет». Например: есть ли препятствие впереди? Если ответ «да», выбираем одно действие; иначе — другое. В Python проверка начинается словом if, которое читается «если». Важно различать проверку и действие после неё: вопрос сам по себе не поворачивает робота.',
 example:'Правило для прогулки: если идёт дождь, возьми зонт; иначе оставь его дома. «Идёт дождь?» — проверка условия. «Взять зонт» — действие для ответа «да». Программа тоже связывает результат проверки с действием.',
 goal:'Выбери слово, которым в программе начинается проверка «если».',steps:['Отдели вопрос-условие от последующего действия.','Найди вариант, который означает «если», а не «повторить» или «показать».','Проверь выбор и прочитай объяснение.'],success:'Ты различаешь условие и действие, которое зависит от него.'},
 g3_m3_l7:{
 explanation:'В алгоритме важны и действия, и их порядок. Одно действие может готовить другое: сначала открываем файл, потом читаем его. Если поменять зависимые шаги местами, нужный результат может не получиться. Но не любые два шага обязательно зависят друг от друга — нужно смотреть на задачу. Проверяй, что уже сделано и что требуется следующему действию. Такой мысленный запуск помогает заметить ошибку до выполнения.',
 example:'Чтобы нарисовать синюю линию, сначала выбираем синий цвет, потом проводим линию. Если сначала провести линию, а потом сменить цвет, уже нарисованная линия не станет синей сама. Второе действие не исправляет прошлое автоматически.',
 goal:'Определи, как перестановка зависимых шагов влияет на результат алгоритма.',steps:['Прочитай, какие шаги необходимы и какой готовит следующий.','Мысленно выполни их в изменённом порядке.','Выбери результат и сравни его с разбором.'],success:'Ты объясняешь, почему порядок этих шагов важен.'},
 g3_m4_l1:{concept:"Находим клетки и строим маршрут",
 explanation:'На клетчатой карте место можно описать двумя числами: столбцом и строкой. Горизонтальное направление называют X, вертикальное — Y. В нашей экранной карте столбцы считаются слева направо, строки — сверху вниз, начиная с нуля. Координаты описывают место, а команды робота — движение между местами. Чтобы обойти стену, сначала найди свободные клетки, потом составь маршрут. forward() следует стрелке; right() и left() поворачивают на месте.',
 example:'На другой карте точка имеет координаты (1, 2): столбец 1, строка 2. Если она перешла в (2, 2), изменился только столбец — точка сдвинулась вправо на одну клетку. Два числа помогают описать место точнее, чем слово «там».',
 goal:'Найди старт, цель и стену на карте. Составь свободный маршрут и запусти робота.',steps:['Определи клетки старта и цели по столбцам и строкам.','Выбери путь по свободным клеткам, затем запиши шаги и повороты.','Проверь маршрут запуском: стрелка показывает направление каждого следующего шага.'],success:'Робот достиг цели, не проходя через стену.'},
 g3_m4_l2:{
 explanation:'В двухмерной игре персонаж и отдельные предметы часто представлены рисунками, которые называют спрайтами. Спрайт можно показать в определённом месте, передвинуть или заменить его изображение. Фон и персонаж выполняют разные роли: фон изображает окружение, персонажем управляет программа. Один рисунок ещё не означает движение — программа должна менять положение или кадр. Так мы отделяем внешний вид объекта от его поведения.',
 example:'На фоне леса появляется рисунок лисы. Программа перемещает лису вправо, а фон остаётся на месте. Лиса — отдельный игровой объект со своим изображением, то есть спрайт.',
 goal:'Выбери название отдельного управляемого рисунка в двухмерной игре.',steps:['Вспомни, какой объект программа может двигать отдельно от фона.','Отличи рисунок объекта от команды, звука или целого уровня.','Выбери термин и проверь ответ.'],success:'Ты можешь отличить спрайт персонажа от фона игры.'},
 g3_m4_l3:{
 explanation:'Анимация создаётся сменой изображений — кадров. На каждом кадре поза немного отличается: например, нога персонажа находится в другом положении. Если показывать кадры быстро и в нужном порядке, мы видим движение. Перемещение и анимация — разные вещи: рисунок может ехать по экрану без смены позы. Для бега обычно нужны и смена кадров, и изменение положения.',
 example:'Первый кадр показывает поднятую лапу, второй — лапу на земле, третий — другую поднятую лапу. Повторяем последовательность, и персонаж выглядит шагающим. Если постоянно показывать первый кадр, поза не изменится.',
 goal:'Определи, как смена кадров создаёт видимость бега персонажа.',steps:['Подумай, что меняется между изображениями персонажа.','Отличи смену поз от изменения цвета или просто увеличения картинки.','Выбери ответ и прочитай разбор.'],success:'Ты объясняешь движение через последовательность немного разных кадров.'},
 g3_m4_l4:{concept:"Обходим стену без столкновения",
 explanation:'В игре столкновение означает, что объекты встретились или попытались занять запрещённое место. Программа проверяет это и применяет правило. В нашем тренажёре стена запрещает роботу перейти в занятую клетку. Поворот на месте разрешён, но шаг в стену останавливает маршрут. Поэтому сначала планируй обход по свободным клеткам. Это задание про обход препятствия, а не про сбор монет или подсчёт очков.',
 example:'На другой карте стена стоит в соседней клетке перед роботом. forward() приведёт к остановке. Чтобы обойти её, сначала выбираем другой свободный участок и поворачиваем туда. Поворот меняет направление, но не позволяет пройти сквозь стену.',
 goal:'Доведи робота до цели по свободным клеткам, обойдя препятствие.',steps:['Найди стену и убедись, что первый шаг не ведёт в неё.','Составь обход: поворот на месте, шаги по свободным клеткам, следующий поворот.','Запусти и найди первый шаг в стену, если маршрут остановился. Исправь его.'],success:'Маршрут дошёл до цели без столкновения со стеной.'},
 g3_m4_l5:{
 explanation:'Переменная хранит значение, которое программа может менять. В игре переменная score может хранить число очков. В записи score = score + 10 сначала читаем старое значение справа и прибавляем 10. Затем новое значение записываем в score слева. Здесь знак = означает присваивание, а не проверку равенства как в обычной математической записи. Одно выполнение прибавляет очки один раз.',
 example:'В другой игре счёт равен 6. Команда score = score + 3 сначала вычислит 6 + 3, затем запишет 9. Если выполнить её ещё раз, будет уже 9 + 3 = 12: программа берёт текущее значение.',
 goal:'Определи, как команда из вопроса изменит текущее число очков.',steps:['Прочитай действие справа от знака =.','Рассчитай новое значение из старого, затем представь его запись в переменную.','Выбери описание изменения и проверь ответ.'],success:'Ты понимаешь прибавление к текущему счёту, а не замену его числом после плюса.'},
 g3_m4_l6:{
 explanation:'В игре правила определяют, когда раунд продолжается и когда заканчивается. Таймер хранит оставшееся время и постепенно уменьшает его. Программа проверяет, не достигло ли время нуля. Если правило говорит закончить раунд при нуле, дальше игра останавливается или показывает результат. Победа и окончание времени — разные условия: можно успеть выполнить цель раньше. Всегда сначала читай правила конкретной игры.',
 example:'В учебной игре нужно собрать три флажка за двадцать секунд. Все флажки собраны до конца времени — победа. Время стало нулём, а цель не выполнена — раунд заканчивается без победы. Решение зависит от двух проверяемых условий.',
 goal:'Выбери условие окончания игры на время, описанное в вопросе.',steps:['Уточни, что измеряет таймер.','Отличи оставшееся время от очков и положения героя.','Выбери условие завершения и нажми «Проверить».'],success:'Ты объясняешь окончание раунда через проверку времени.'},
 g3_m4_l7:{
 explanation:'На экранной карте два направления помогают описать движение. Горизонталь — влево и вправо, вертикаль — вверх и вниз. Обычно X обозначает горизонтальное положение, Y — вертикальное. При движении только по горизонтали меняется X, а Y остаётся прежним. Перед работой проверяй подписи осей: в разных средах начало и направление отсчёта могут отличаться. Не путай название оси с командой поворота робота.',
 example:'Точка была в (1, 3), стала в (4, 3). Первое число изменилось, второе нет: высота осталась прежней, точка переместилась горизонтально. В другом случае (1, 3) → (1, 2) движение вертикальное.',
 goal:'Определи, какая ось описывает движение влево и вправо.',steps:['Представь горизонтальную линию на экране.','Вспомни, какое число меняется при движении вдоль неё.','Выбери ось и проверь ответ.'],success:'Ты различаешь горизонтальное и вертикальное изменение координат.'},
 g3_m5_l1:{
 explanation:'Когда открываешь сайт, данные проходят между устройствами по соединениям. На нашей схеме устройства обозначены узлами, соединения — линиями. Начало пути — клиент, который просит данные; конец — сервер, который отвечает. У каждой линии подписана задержка: время передачи в миллисекундах, или мс. Для всего пути складываем задержки его линий. Короткая линия на рисунке не обязательно быстрая: сравниваем числа. Переходить можно только к узлу, соединённому с текущим.',
 example:'На другой схеме путь через два участка занимает 7 + 9 = 16 мс. Прямое соединение занимает 22 мс. Путь через промежуточный узел быстрее, хотя на рисунке выглядит длиннее. Оба маршрута должны вести к одному серверу, иначе сравнение не решает задачу.',
 goal:'Выбери соединённые узлы от клиента до сервера так, чтобы суммарная задержка была не больше 50 мс.',steps:['Найди клиента, сервер и задержки на линиях.','Нажимай доступные соседние узлы, складывая задержки выбранных участков.','Сравни итог с ограничением. Если путь не подошёл, сбрось маршрут и попробуй другой.'],success:'Маршрут заканчивается на сервере и укладывается в 50 мс.'},
 g3_m5_l2:{
 explanation:'Браузер — программа, с помощью которой открывают сайты. Когда ты вводишь адрес, браузер отправляет запрос: просит данные страницы. Сервер — другая программа, которая получает запрос и подготавливает ответ. Браузер принимает ответ и показывает страницу человеку. В этом обмене браузер играет роль клиента. Один и тот же сайт может отвечать многим клиентам; твоему компьютеру не нужно хранить весь интернет.',
 example:'Ты открываешь страницу школьной библиотеки. Браузер просит список книг у сервера библиотеки. Сервер отправляет данные, браузер показывает названия. Клиент запрашивает, сервер отвечает.',
 goal:'Определи роль браузера при открытии сайта.',steps:['Вспомни, кто отправляет запрос, а кто отвечает.','Сопоставь роль браузера с вариантами.','Выбери ответ и прочитай разбор.'],success:'Ты различаешь клиента и сервер по их действиям.'},
 g3_m5_l3:{
 explanation:'Человеку удобно запомнить имя сайта, например library.example. Для сетевого соединения нужен адрес устройства — IP-адрес. DNS помогает узнать, какому адресу соответствует имя сайта. Это похоже на справочник: по имени находим нужную запись. DNS не создаёт страницу и не отвечает за её рисунки; он помогает найти адрес. После этого браузер может обратиться к серверу.',
 example:'В телефонной книге по имени «Библиотека» находят номер, а затем звонят. В сети по имени сайта узнают адрес, затем отправляют запрос. Справочник помогает найти получателя, но не разговаривает вместо него.',
 goal:'Выбери, какую работу выполняет DNS.',steps:['Отдели поиск адреса от показа страницы и хранения файлов.','Вспомни аналогию со справочником.','Выбери описание работы и проверь ответ.'],success:'Ты объясняешь DNS как поиск адреса по имени сайта.'},
 g3_m5_l4:{
 explanation:'HTML описывает части страницы: заголовок, абзац, кнопку и другие элементы. Тег — отметка, которая сообщает браузеру роль части текста. Для главного заголовка используем h1: сначала открывающий <h1>, затем текст, затем закрывающий </h1>. Косая черта в закрывающем теге показывает конец элемента. Код пишем в редакторе, а результат смотрим в предпросмотре. В этом задании нужен главный заголовок; абзац и оформление добавлять не обязательно.',
 example:'На другой странице код <h1>Дневник экспедиции</h1> создаёт главный заголовок. Ниже можно написать <p>Сегодня мы нашли следы.</p> — это уже обычный абзац. Теги отмечают разные роли, даже если текст посвящён одной теме.',
 goal:'Внутри <main> добавь главный заголовок с собственным текстом, используя h1, и нажми «Запустить».',steps:['Открой код и найди место между <main> и </main>.','Вместо комментария напиши открывающий тег, свой заголовок и закрывающий тег.','Посмотри страницу в результате, затем нажми «Запустить» для проверки. Если не получилось, проверь название тега и косую черту.'],success:'На странице есть элемент h1 с твоим заголовком.'},
 g3_m5_l5:{
 explanation:'HTML-кнопка — элемент, который пользователь может нажать. Её создаёт тег button: между <button> и </button> пишется подпись. Подпись должна объяснять действие, например «Открыть дневник». Сам тег создаёт кнопку, но не программирует сохранение, запуск ракеты или переход. Для такого поведения понадобится отдельный код. В нашей практике нужно только создать кнопку: цвет, размеры и действие не являются условиями проверки.',
 example:'Код <button>Показать маршрут</button> создаёт кнопку с понятной подписью. Она появится на странице, но маршрут сам по себе не откроется: пока мы написали только элемент интерфейса.',
 goal:'Добавь внутрь <main> кнопку button с собственной понятной подписью и запусти проверку.',steps:['Открой код и найди место для нового элемента.','Напиши <button>, подпись и </button>.','Посмотри кнопку в результате и нажми «Запустить». Если проверка не прошла, проверь оба тега.'],success:'В HTML есть элемент button; ты понимаешь, что его действие ещё не запрограммировано.'},
 g3_m5_l6:{
 explanation:'Когда данные идут по сети, их нужно защищать от постороннего чтения по дороге. HTTPS шифрует соединение браузера с сайтом. Это особенно важно для паролей и других личных сведений. Но защищённое соединение не доказывает честность сайта: мошенник тоже может использовать HTTPS. Поэтому проверяем и соединение, и настоящий адрес сайта. Если адрес незнакомый или сообщение просит секретный код, остановись и попроси взрослого помочь.',
 example:'Представь запечатанное письмо: прохожий не читает его содержимое, но это ещё не доказывает, что получатель честный. Так и HTTPS защищает передачу, а доверие к сайту требует отдельной проверки.',
 goal:'Определи, зачем нужна защита HTTPS при передаче пароля.',steps:['Вспомни, что шифрование защищает данные во время передачи.','Не путай защиту соединения с обещанием честности сайта.','Выбери ответ и прочитай разбор.'],success:'Ты объясняешь назначение HTTPS и не считаешь его гарантией безопасности сайта.'},
 g3_m5_l7:{
 explanation:'На странице название материала и основной текст выполняют разные задачи. Главный заголовок сообщает, о чём страница; HTML отмечает его тегом h1. Абзац содержит часть рассказа или объяснения; его отмечает p. Кнопка button предлагает действие. Выбираем тег по смыслу элемента, а не только по размеру букв. Изменить размер можно оформлением, но роль элемента задаёт его разметка.',
 example:'<h1>Школьный сад</h1> — название страницы. <p>Мы посадили яблоню.</p> — текст рассказа. <button>Посмотреть фото</button> — приглашение к действию. Каждый элемент имеет свою роль.',
 goal:'Выбери тег для главного заголовка статьи.',steps:['Определи, нужен заголовок, абзац или кнопка.','Сравни роль элемента с названиями тегов.','Проверь ответ и объясни, почему другие элементы не подходят.'],success:'Ты выбираешь тег по роли части страницы.'},
 g3_m6_l1:{
 explanation:'Сообщение или картинка могут выглядеть убедительно, но оказаться выдумкой. Чтобы проверить утверждение, ищем источник: кто сообщил и можно ли найти подтверждение. Проверяем дату, доказательства и то, не выдаёт ли автор мнение за факт. Очень необычная картинка сама по себе не доказательство: её могли изменить. В учебном детекторе внимательно читай карточку и объяснение после ответа. Если сведений недостаточно, в жизни лучше сказать «пока не знаю» и проверить, чем угадывать.',
 example:'Подпись обещает, что найдено животное, которое живёт на облаках. Красивый рисунок не подтверждает открытие. Сначала ищем, кто это исследовал, где опубликовано сообщение и есть ли независимое подтверждение.',
 goal:'Рассмотри каждую карточку и выбери, подтверждена ли история или это выдумка в учебном задании.',steps:['Прочитай историю и признаки источника, а не только посмотри на картинку.','Выбери вариант и прочитай объяснение результата.','При ошибке попробуй ещё раз; после верного выбора переходи к следующей карточке до конца набора.'],success:'Все карточки пройдены; ты называешь признаки, по которым оценивал историю.'},
 g3_m6_l2:{
 explanation:'Пароль защищает вход в аккаунт. Короткое простое слово, имя или ряд цифр легче подобрать. Длинный пароль, который трудно угадать, защищает лучше; не используй один пароль для разных аккаунтов. В жизни создавать и хранить пароли ребёнку стоит вместе с доверенным взрослым. Никому не сообщай настоящий пароль в чате или в учебном ответе. В этом задании мы только сравниваем придуманные примеры — использовать их для своего аккаунта нельзя.',
 example:'Сравним «1111» и длинную случайную последовательность. Первый вариант короткий и очень распространённый, поэтому легко проверяется при подборе. Во втором больше возможных сочетаний. Но опубликованный пример всё равно не годится как личный секрет.',
 goal:'Сравни учебные примеры паролей и выбери наиболее устойчивый к подбору. Настоящий пароль не вводи.',steps:['Проверь длину и предсказуемость каждого примера.','Отметь имена, обычные слова и простые последовательности как слабые признаки.','Выбери лучший из предложенных вариантов и прочитай разбор.'],success:'Ты объясняешь выбор через длину и трудность угадывания.'},
 g3_m6_l3:{
 explanation:'Одного пароля иногда недостаточно: его могут узнать посторонние. Двухфакторная защита добавляет второй способ подтверждения, например код приложения на твоём устройстве. Для входа нужны оба шага, а не один из них. Не пересылай код даже человеку, который представляется сотрудником игры: он может использовать его для входа. Если пришёл неожиданный запрос подтверждения, не одобряй его и покажи взрослому. Второй фактор помогает, но его тоже нужно беречь.',
 example:'Кто-то узнал пароль, но при входе система просит подтверждение с устройства владельца. Без него вход не завершается. Если владелец отдаст код мошеннику, дополнительная защита уже не поможет.',
 goal:'Определи, как второй фактор мешает входу по украденному паролю.',steps:['Представь, что пароль уже известен постороннему.','Уточни, какое дополнительное подтверждение нужно для входа.','Выбери ответ и объясни, почему нельзя пересылать код.'],success:'Ты понимаешь необходимость второго подтверждения и его секретность.'},
 g3_m6_l4:{
 explanation:'Фишинг — обман, с помощью которого пытаются получить пароль, код или другие секретные сведения. Мошенник может притвориться знакомой игрой или службой. Проверяем не только логотип, но и адрес отправителя, просьбу, ссылку и вложение. Срочность и угроза закрыть аккаунт могут заставить действовать без проверки. В тренажёре нажатие на подозрительное место означает его проверку, а не открытие настоящей ссылки. В жизни не переходи по такой ссылке: покажи сообщение взрослому.',
 example:'Письмо с логотипом игры требует немедленно отправить код входа. Логотип легко скопировать, а просьба о секретном коде опасна. Останавливаемся и проверяем ситуацию через знакомый официальный способ связи, не отвечая письму.',
 goal:'Проверь подозрительные места учебного письма и найди все предусмотренные признаки обмана.',steps:['Нажми на отправителя, срочную просьбу, ссылку или вложение, чтобы проверить их.','Прочитай результат каждой проверки: что именно вызывает подозрение.','Следи за списком найденных признаков. Когда всё найдено, заверши расследование кнопкой задания.'],success:'Все признаки письма найдены; ты объясняешь причины подозрения.'},
 g3_m6_l5:{
 explanation:'Личные сведения помогают узнать, кто ты и где тебя найти: адрес дома, телефон, школа, маршрут и местоположение. Они могут попасть в интернет не только через текст, но и на фоне фотографии. Интерес к книге или игре обычно можно обсудить без таких подробностей. Но имя любимой игры не делает безопасной любую публикацию: проверь всё сообщение целиком. Опубликованное могут скопировать, поэтому удалить все копии позже не всегда получится.',
 example:'На фото рисунка случайно видна тетрадь с фамилией и названием школы. Главный объект безобидный, но фон раскрывает сведения. Перед публикацией вместе со взрослым убираем лишнее или выбираем другой снимок.',
 goal:'Выбери сообщение, которое не раскрывает личные сведения ребёнка.',steps:['Проверь, можно ли по каждому варианту найти человека или связаться с ним лично.','Отдели обсуждение интересов от адресов, телефонов и маршрутов.','Выбери безопасный из предложенных вариантов и прочитай разбор.'],success:'Ты замечаешь личные сведения и в явном тексте, и в деталях публикации.'},
 g3_m6_l6:{
 explanation:'Если в чате тебя оскорбляют, не нужно терпеть это или отвечать такой же грубостью. Прекрати неприятный разговор и обратись к доверенному взрослому. Можно сохранить сообщение, пожаловаться через сервис и заблокировать обидчика. Если сохранять сообщение опасно или очень тяжело, помощь взрослого важнее снимка экрана. Тот, кого обижают, не виноват в чужих поступках. Помощь можно попросить и после того, как уже ответил или растерялся.',
 example:'Игрок продолжает писать обидные сообщения. Ребёнок прекращает переписку и показывает её родителю или учителю. Вместе они выбирают блокировку и жалобу. Отвечать оскорблением, чтобы «победить», не требуется.',
 goal:'Выбери безопасное действие при грубости и дразнении в игровом чате.',steps:['Подумай, какой вариант прекращает вред и помогает получить поддержку.','Не выбирай ответ, который усиливает перепалку или раскрывает личные данные.','Проверь выбор и назови взрослого, к которому можешь обратиться.'],success:'Ты знаешь, как остановить разговор и попросить помощи.'},
 g3_m6_l7:{
 explanation:'Неожиданное сообщение о выигрыше может быть приманкой. Особенно подозрительно, если ты не участвовал в конкурсе, тебя торопят или требуют пароль, код и оплату. Не нажимай кнопку только потому, что она обещает подарок. Сначала остановись и покажи сообщение доверенному взрослому. Проверяют конкурс через известный официальный источник, а не через ссылку из самого письма. Если уже нажал или отправил что-то, расскажи взрослому сразу: скрывать ошибку не нужно.',
 example:'Письмо обещает бесплатный игровой предмет, но просит сначала оплатить получение и отправить код входа. Эти просьбы не подтверждают подарок — они показывают риск обмана. Ничего не отправляем и обращаемся за помощью.',
 goal:'Выбери безопасный первый шаг при неожиданном письме о выигрыше.',steps:['Заметь обещание, срочность и просьбы о секретах или деньгах.','Выбери паузу и проверку вместо немедленного перехода по ссылке.','Прочитай разбор и объясни, кому покажешь такое сообщение.'],success:'Ты умеешь остановиться и проверить предложение, не передавая секреты.'},
 "g3_m7_l1":{"explanation": "Некоторые программы выполняют заранее записанные правила. Модель машинного обучения настраивается на примерах: в данных она ищет закономерности, которые помогают сделать предположение для нового случая. Это не человеческое понимание и не волшебство. Качество результата зависит от примеров и проверки. Даже обученная модель может ошибаться.", "example": "Модели показывают разные рисунки птиц и подписывают их. Затем дают новый рисунок и проверяют ответ. Калькулятор же складывает числа по заданному правилу, а не учится сложению по фотографиям.", "goal": "Сравни обучение модели на примерах с выполнением готового правила.", "steps": ["Прочитай, откуда программа получает способ решения.", "Отдели обучение на данных от выполнения арифметического правила.", "Выбери ответ и прочитай разбор."], "success": "Ты объясняешь обучение через примеры, не приписывая модели человеческое мышление."},
 "g3_m7_l2":{"explanation": "Чтобы обучать модель, сначала готовят примеры с правильными подписями. В нашем задании это два набора: кошки и собаки. Посмотри на животное, а не только на цвет или фон, и выбери правильный набор. Ошибочная подпись запутает будущую модель. После подготовки примеров нужно проверить работу на других примерах: знакомый рисунок ещё не показывает, что правило подходит для нового. Это учебная модель, которая не заменяет настоящую проверку.", "example": "В другом наборе различают велосипеды и самокаты. Красный велосипед остаётся велосипедом, как и синий. Если все красные предметы подписать самокатами, данные будут учить неверному признаку.", "goal": "Подпиши карточки кошек и собак, затем проверь набор кнопкой тренажёра.", "steps": ["Прочитай названия двух наборов.", "Перенеси карточку или выбери её и нажми нужную корзину. Ошибочную карточку можно переложить.", "Проверь примеры и пройди дальнейшую проверку, если тренажёр её предлагает."], "success": "Все карточки подписаны по виду животного, а не по фону."},
 "g3_m7_l4":{"explanation": "Модель делает предположение по признакам, которые встретила в учебных примерах. Если разные предметы похожи, она может их перепутать. Круглая форма и полоски бывают у разных объектов. Один совпавший признак ещё не доказывает, что предмет тот же. Разнообразные данные и новые проверочные примеры помогают обнаружить ошибки, но не гарантируют безошибочность.", "example": "Если в наборе все лодки белые, модель может слишком сильно связать белый цвет с лодкой. Белый рюкзак покажет, почему одного цвета недостаточно.", "goal": "Объясни, почему похожие признаки могут привести к ошибке распознавания.", "steps": ["Найди общие признаки двух предметов.", "Подумай, какие различия модель могла не учесть.", "Выбери причину ошибки и проверь ответ."], "success": "Ты связываешь ошибку с признаками и учебными примерами."},
 "g3_m7_l5":{"explanation": "Запрос к ИИ должен ясно описывать нужный результат. Назови объект, действие и важные детали: место, цвет или стиль, если они действительно нужны. Не добавляй противоречивые требования. Подробность полезна, когда уточняет задачу, а не просто делает просьбу длиннее. После ответа проверь результат: понятный запрос не гарантирует, что всё будет выполнено.", "example": "Вместо «нарисуй что-нибудь» можно попросить: «Нарисуй зелёную черепаху на песке в стиле карандашного рисунка». Теперь известны объект, место и стиль.", "goal": "Сравни запросы и выбери тот, который яснее описывает желаемую картинку.", "steps": ["Проверь, назван ли объект и важные детали.", "Ищи понятные требования без противоречий.", "Выбери запрос и объясни, чего ждать от результата."], "success": "Ты оцениваешь ясность запроса, а не только его длину."},
 "g3_m7_l6":{"explanation": "Распознавание речи превращает услышанные слова в текст. Микрофон получает звук, программа анализирует его и предлагает запись слов. Это отличается от записи аудио: аудиофайл хранит звук, а распознавание создаёт текст. Шум и похожие слова могут вызвать ошибку. Поэтому запись надо прочитать и исправить, прежде чем отправлять.", "example": "Ты произнёс «купить молоко», а приложение показало эти слова в заметке. Если оно лишь сохранило запись голоса, это ещё не превращение речи в текст.", "goal": "Определи название технологии, которая записывает произнесённые слова буквами.", "steps": ["Уточни, что получилось: звук или текст.", "Отличи распознавание от воспроизведения речи.", "Выбери ответ и проверь объяснение."], "success": "Ты различаешь аудиозапись и текст, полученный из речи."},
 "g3_m7_l7":{"explanation": "Набор данных, или датасет, — собрание примеров для определённой задачи. Это могут быть картинки, записи звука или строки таблицы. Иногда у примера есть подпись: что на картинке или к какой группе он относится. Примеры должны соответствовать задаче и быть достаточно разнообразными. Сам набор ещё не является обученной моделью: модель создают и проверяют с помощью данных.", "example": "Для распознавания дорожных знаков собирают изображения разных знаков и их подписи. Список любимых песен не подходит для этой задачи, хотя тоже содержит данные.", "goal": "Выбери, что называют набором данных в машинном обучении.", "steps": ["Найди вариант, описывающий собрание примеров.", "Отдели данные от программы и результата её работы.", "Выбери ответ и назови пример такого набора."], "success": "Ты объясняешь назначение набора примеров."},
 "g3_m8_l1":{"explanation": "В таблице пересечение столбца и строки называется ячейкой. Адрес B2 означает столбец B, строка 2. Формула начинается с = и может использовать адреса ячеек вместо готовых чисел. Чтобы найти стоимость покупки, умножаем цену одной вещи на количество. Знак умножения в формуле — *. Ссылки позволяют пересчитать результат, если данные изменятся.", "example": "В другой таблице цена записана в E3, количество — в F3. Формула =E3*F3 умножает эти значения. При цене 7 и количестве 3 получится 21. Для своего задания адреса надо взять из его таблицы.", "goal": "Вычисли стоимость в строке 2: используй ячейки с ценой и количеством.", "steps": ["Найди заголовки цены и количества и адреса их ячеек.", "В поле формулы напиши =, адрес цены, *, адрес количества.", "Проверь формулу кнопкой задания и сравни результат с умножением вручную."], "success": "Формула использует цену и количество нужной строки и даёт стоимость."},
 "g3_m8_l2":{"explanation": "Общий итог нескольких покупок получают сложением их стоимостей. Функция SUM складывает значения выбранных ячеек. Диапазон обозначает участок таблицы: двоеточие между первым и последним адресом включает обе границы и ячейки между ними. Сначала выясни, что уже вычислено в каждой строке, затем выбери столбец итогов. Складывать цены без учёта количества — другая задача.", "example": "В другой таблице =SUM(E3:E5) складывает E3, E4 и E5. Если там 4, 6 и 9, сумма равна 19. Двоеточие не пропускает среднюю строку.", "goal": "Найди общий итог стоимостей в D2–D4 с помощью формулы.", "steps": ["Прочитай, что хранится в столбце D.", "В поле формулы задай сумму диапазона нужных строк, начиная с =.", "Запусти проверку и сравни со сложением трёх значений вручную."], "success": "Сумма включает все нужные стоимости и не захватывает лишние строки."},
 "g3_m8_l3":{"explanation": "Диаграмма показывает данные так, чтобы их было удобнее сравнивать. У столбчатой диаграммы высота столбца соответствует величине. Но сначала нужно прочитать название, подписи и единицы измерения. Высокий столбец не всегда означает «лучше»: это зависит от того, что измеряли. Диаграмма помогает видеть различия, но исходные данные и шкала тоже важны.", "example": "Сравниваем число прочитанных книг: у одного ученика 2, у другого 5. Более высокий столбец показывает больше книг, а не возраст или оценку ученика.", "goal": "Выбери, зачем данные показывают диаграммой.", "steps": ["Подумай, что наглядное сравнение помогает заметить.", "Не путай показ данных с их автоматическим исправлением.", "Выбери ответ и объясни на примере."], "success": "Ты называешь сравнение и поиск различий по данным."},
 "g3_m8_l4":{"explanation": "При сортировке по возрастанию числа ставят от меньшего к большему. В этом тренажёре сравниваются соседние числа. Если левое больше правого, их надо поменять местами; иначе оставляем порядок. После обмена список ещё может быть не отсортирован: продолжаем сравнения. Равные числа не нарушают возрастание.", "example": "В другом списке 5, 2, 4 сначала сравниваем 5 и 2 и меняем их. Получается 2, 5, 4. Теперь сравниваем 5 и 4: после обмена 2, 4, 5.", "goal": "Расставь числа по возрастанию, решая, менять ли выделенную соседнюю пару.", "steps": ["Сравни только два выделенных числа.", "Выбери обмен, если левое больше; иначе оставь порядок.", "Продолжай по подсказкам тренажёра до завершения и проверь весь список."], "success": "Каждое следующее число не меньше предыдущего."},
 "g3_m8_l5":{"explanation": "В таблице записей каждой строке соответствует один объект, а столбцы описывают его свойства. У книги могут быть название, автор и год. Одинаковая структура помогает искать и сравнивать записи: например, отбирать книги одного автора. База данных хранит организованные записи и позволяет обращаться к ним по условиям. Она не проверяет автоматически, правдивы ли введённые сведения.", "example": "В библиотечной таблице можно найти книги нужного автора по столбцу «Автор». В длинном свободном тексте те же сведения сложнее искать и сравнивать одинаковым способом.", "goal": "Определи преимущество организованных записей при поиске данных.", "steps": ["Представь, какие свойства собраны в столбцах.", "Сравни поиск по условию со чтением свободного текста.", "Выбери ответ и прочитай разбор."], "success": "Ты объясняешь удобство поиска и обработки структурированных данных."},
 "g3_m8_l6":{"explanation": "У разных людей или предметов может быть одинаковое имя. Чтобы точно различать записи, им дают уникальный идентификатор — ID. ID указывает на определённую запись, а имя описывает её для человека. Уникальность нужна внутри системы: одна запись не должна случайно получить номер другой. ID не заменяет все свойства и не делает запись секретной.", "example": "В библиотеке две книги называются «Приключения». У одной номер 41, у другой 62. По номеру выбираем нужный экземпляр, даже если названия совпадают.", "goal": "Объясни, зачем записи нужен уникальный ID.", "steps": ["Представь две записи с одинаковым именем.", "Подумай, как выбрать ровно одну из них.", "Выбери назначение ID и проверь ответ."], "success": "Ты различаешь имя и уникальный идентификатор записи."},
 "g3_m8_l7":{"explanation": "Таблица должна отличать текст от команды вычисления. Знак = в начале сообщает, что дальше записана формула. После него может идти вычисление, ссылка на ячейку или функция. Без этого знака похожая запись может остаться обычным текстом. Результат формулы и её запись — разные вещи: в ячейке можно видеть число, хотя за ним стоит вычисление.", "example": "Запись =3+4 задаёт вычисление и даёт 7. Надпись «3+4» без признака формулы может восприниматься как текст. Сначала отмечаем вычисление, затем пишем само действие.", "goal": "Выбери обязательный начальный символ формулы.", "steps": ["Вспомни, как таблица узнаёт, что надо считать.", "Отдели начало формулы от знака умножения или имени функции.", "Выбери ответ и проверь его."], "success": "Ты отличаешь формулу от обычной текстовой записи."},
 "g3_m9_l1":{"explanation": "Удобный экран помогает человеку понять, что делать, и выполнить задачу без лишних трудностей. UX описывает опыт использования: можно ли найти действие, понять результат и исправить ошибку. Красивые цвета сами по себе не делают экран понятным. Сначала выясняют задачу пользователя, затем проверяют, помогает ли интерфейс её решить.", "example": "В игре кнопка «Продолжить» видна и понятно возвращает к прохождению. Если такую кнопку спрятать в непонятном значке, игрок будет искать её, даже на красивом экране.", "goal": "Выбери, за какую сторону удобства отвечает UX-дизайнер.", "steps": ["Подумай о действиях пользователя, а не только о картинках.", "Сравни понятность работы с декоративным оформлением.", "Выбери ответ и объясни причину."], "success": "Ты связываешь UX с решением задачи пользователя."},
 "g3_m9_l2":{"explanation": "Макет экрана — план, на котором видно расположение основных блоков. Заголовок объясняет, где мы находимся, содержание показывает нужную информацию, кнопка предлагает действие. Сначала выбираем блок по его роли, затем помещаем в подходящую область. Если расположение не подходит, блок можно убрать и заменить. В задании используем готовые детали, а не пишем код страницы.", "example": "Для экрана чтения название рассказа ставим сверху, текст — в основной части, кнопку перехода — после текста. Так человек сначала понимает тему, потом читает, затем выбирает действие.", "goal": "Собери экран из подходящих блоков и запусти его проверку.", "steps": ["Прочитай роли деталей и областей экрана.", "Выбери деталь и нажми нужную область или перетащи её туда.", "Проверь экран; при ошибке замени неподходящую деталь."], "success": "Все нужные области заполнены блоками соответствующей роли."},
 "g3_m9_l3":{"explanation": "Кнопка удаления должна ясно предупреждать о последствиях. Красный цвет часто используют для опасного или необратимого действия. Но одного цвета недостаточно: нужна понятная подпись и предупреждение о том, что будет удалено. Люди могут по-разному различать цвета. Главное действие должно быть узнаваемо и по тексту, а не только по оттенку.", "example": "Кнопка «Удалить рисунок навсегда» с предупреждением понятнее безымянного красного квадрата. Перед подтверждением человек должен понимать, можно ли вернуть работу.", "goal": "Выбери обычный предупреждающий цвет для необратимого удаления.", "steps": ["Определи, опасно ли действие и можно ли его отменить.", "Вспомни цвет предупреждения, сохраняя необходимость подписи.", "Выбери ответ и прочитай разбор."], "success": "Ты понимаешь роль предупреждения, не полагаясь только на цвет."},
 "g3_m9_l4":{"explanation": "Значок помогает быстро узнать действие, если его смысл знаком. Настройки часто обозначают шестерёнкой. Однако незнакомый значок можно понять неверно, поэтому рядом полезна подпись. Один и тот же рисунок не объясняет все действия автоматически. Проверяй, соответствует ли значок ожидаемому действию.", "example": "Рядом с шестерёнкой написано «Настройки». Такая пара помогает понять, где изменить звук. Значок корзины обычно обещает удаление, поэтому для настройки звука он запутает пользователя.", "goal": "Выбери значок, который часто используют для настроек.", "steps": ["Вспомни знакомые действия значков.", "Сопоставь их с изменением параметров приложения.", "Выбери ответ и объясни, зачем полезна подпись."], "success": "Ты связываешь значок с действием и понимаешь роль текста."},
 "g3_m9_l5":{"explanation": "До кнопки должно быть удобно дотянуться, а попасть в неё — легко. На телефоне, который держат одной рукой, большой палец обычно лучше достигает нижней части экрана. Но удобство зависит от размера телефона и руки человека. Поэтому размещение проверяют на реальном использовании. Кнопки не должны быть слишком маленькими или тесно стоять рядом.", "example": "Если часто нужная кнопка спрятана в дальнем верхнем углу, приходится менять хват. Кнопка в доступной нижней области может быть удобнее, если не закрывает важный текст.", "goal": "Выбери обычно более доступную область для большого пальца при удержании телефона одной рукой.", "steps": ["Представь свой хват телефона.", "Сравни близкую и дальнюю области, не перекрывая содержимое.", "Выбери ответ и прочитай пояснение."], "success": "Ты связываешь размещение с доступностью, а не с украшением."},
 "g3_m9_l6":{"explanation": "Тестирование проверяет, работает ли приложение как задумано. Сначала определяют ожидаемый результат, потом выполняют действия и сравнивают фактический результат с ожиданием. Найденную ошибку описывают так, чтобы другой человек мог её повторить. Проверяют не только удачный случай, но и неверный ввод или отмену. Тестирование помогает найти проблемы, но один успешный запуск не доказывает отсутствие всех ошибок.", "example": "Ожидаем, что кнопка добавит один балл. Нажимаем её три раза и проверяем счёт. Если второй раз балл не прибавился, записываем порядок действий и результат.", "goal": "Выбери, какую работу выполняет специалист по тестированию.", "steps": ["Вспомни сравнение ожидаемого и фактического результата.", "Отдели проверку работы от создания рисунков или рекламы.", "Выбери ответ и приведи пример проверки."], "success": "Ты описываешь тестирование через действия, ожидание и результат."},
 "g3_m9_l7":{"explanation": "Вайрфрейм — простой план экрана без подробного украшения. На нём показывают, где будут заголовок, содержание, поля и кнопки. Его делают до сложного оформления, чтобы проверить порядок и понятность действий. Изменить такой план проще, чем переделать готовое приложение. Это не фотография результата и не работающая программа.", "example": "Прямоугольник сверху обозначает заголовок, большой блок — текст, маленький блок ниже — кнопку. Даже без рисунков видно, что человек сначала прочитает информацию, затем нажмёт действие.", "goal": "Определи, что представляет собой вайрфрейм.", "steps": ["Подумай, что нужно проверить до оформления и программирования.", "Отдели план расположения от готового приложения.", "Выбери ответ и объясни пользу макета."], "success": "Ты понимаешь макет как план структуры экрана."},
 "g3_m10_l1":{"explanation": "Логическое правило связывает входные сигналы с результатом. В этом тренажёре правило OR, или ИЛИ: достаточно хотя бы одного включённого входа. Выключенный вход обозначают 0, включённый — 1. Если оба входа выключены, выход выключен; если включён один или оба, выход включён. Смотри на требование текущего раунда: иногда нужно получить выключенный выход.", "example": "Напоминание появляется после кнопки на часах ИЛИ кнопки на телефоне. Любой из способов подходит, а нажатие обеих кнопок не отменяет напоминание.", "goal": "Меняй рубильники A и B, чтобы выполнить условие раунда по правилу ИЛИ.", "steps": ["Прочитай нужное состояние выхода и ограничения входов.", "Переключи рубильники и посмотри на лампу.", "Нажми «Проверить схему» и пройди все раунды."], "success": "Состояния входов и выхода соответствуют условию каждого раунда."},
 "g3_m10_l2":{"explanation": "Правило AND, или И, требует одновременного выполнения двух условий. Если включён только A или только B, выход остаётся выключенным. Выход включается лишь при двух включённых входах. Это отличается от ИЛИ, где хватает одного. В каждом раунде внимательно читай, какое состояние выхода требуется, затем выбирай входы.", "example": "Шкаф открывается, если есть ключ И введён верный код. Только ключ без кода недостаточен, как и код без ключа. Оба требования выполняются вместе.", "goal": "Настрой входы A и B по правилу И и проверь условие каждого раунда.", "steps": ["Прочитай условие раунда.", "Переключи входы, помня, что для включения нужны оба.", "Проверь схему и исправь входы, если результат не подходит."], "success": "Все раунды решены по правилу одновременного выполнения условий."},
 "g3_m10_l3":{"explanation": "ИЛИ объединяет два возможных способа получить результат. Достаточно одного истинного условия, но оба истинных тоже подходят. Единственный случай выключенного выхода — оба входа выключены. Слово «или» в разговоре иногда означает выбор только одного, но в этом логическом правиле используется включающее ИЛИ. Всегда читай определение правила.", "example": "Можно войти в помещение по пропуску ИЛИ с разрешением дежурного. Наличие обоих оснований не запрещает вход. Отсутствие обоих не даёт разрешения.", "goal": "Выбери, когда включается выход логического ИЛИ.", "steps": ["Проверь случаи одного, двух и ни одного включённого входа.", "Не исключай случай двух включённых входов.", "Выбери правило и проверь ответ."], "success": "Ты понимаешь выражение «хотя бы одно», включая оба условия."},
 "g3_m10_l4":{"explanation": "Правило NOT, или НЕ, меняет значение одного сигнала на противоположное. На входе 0 — на выходе 1. На входе 1 — на выходе 0. Здесь только один вход: складывать сигналы или выбирать один из двух не нужно. Название напоминает отрицание условия.", "example": "В модели сигнал 1 означает «дверь открыта». Условие «дверь НЕ открыта» тогда ложно и даёт 0. Если дверь закрыта, это отрицание даёт 1.", "goal": "Определи выход НЕ для значения входа из вопроса.", "steps": ["Прочитай исходный сигнал.", "Замени его противоположным из пары 0 и 1.", "Выбери результат и проверь ответ."], "success": "Ты применяешь отрицание к одному входному сигналу."},
 "g3_m10_l5":{"explanation": "Датчик измеряет или замечает изменение вокруг устройства. Датчик движения обнаруживает перемещение, датчик температуры измеряет температуру. Сам датчик не обязательно включает лампу: он передаёт данные программе. Программа проверяет правило и отправляет команду устройству. Поэтому выбираем датчик по тому, что нужно обнаружить.", "example": "Чтобы включить обогрев при холоде, нужен датчик температуры. Для обнаружения вошедшего человека нужен другой признак — движение. Измерение и действие устройства имеют разные роли.", "goal": "Выбери датчик, который обнаруживает движение человека для включения света.", "steps": ["Определи, какое событие нужно заметить.", "Сравни его с тем, что измеряют разные датчики.", "Выбери датчик и проверь ответ."], "success": "Ты связываешь тип датчика с обнаруживаемым событием."},
 "g3_m10_l6":{"explanation": "Автоматизация задаёт правило: при определённом событии выполнить действие. Нужно указать, что проверяет система и что она делает при выполнении условия. Устройство не угадывает желание человека. Датчик даёт сведения, программа проверяет условие, исполнитель совершает действие. Сценарий нужно проверить и для случая, когда условие не выполняется.", "example": "Если в комнате темно и обнаружено движение, включить лампу. Темнота и движение — условия, включение лампы — действие. Просто фраза «сделай уютно» не задаёт точного правила.", "goal": "Выбери описание сценария автоматизации.", "steps": ["Найди связь события или условия с действием.", "Отдели правило от названия устройства и случайной команды.", "Выбери ответ и назови условие и действие в примере."], "success": "Ты можешь сформулировать понятное правило автоматического действия."},
 "g3_m10_l7":{"explanation": "Безопасная работа начинается с умения остановиться, когда что-то непонятно или тревожно. Не передавай пароль, код входа, домашний адрес и маршрут незнакомым людям. Не нужно выполнять просьбу только потому, что тебя торопят или обещают подарок. Покажи сообщение доверенному взрослому и вместе решите, что делать. Если уже ошибся, помощь всё равно доступна: расскажи сразу, не скрывай случившееся.", "example": "Новый знакомый в игре просит показать дорогу от школы до дома. Не отправляем маршрут и обращаемся к взрослому. Даже приятная беседа не делает такую просьбу безопасной.", "goal": "Выбери безопасное правило обращения с личными сведениями в интернете.", "steps": ["Проверь, какие сведения и кому предлагают передать.", "Выбери защиту секретов и помощь взрослого вместо поспешного ответа.", "Прочитай разбор и объясни первый безопасный шаг."], "success": "Ты умеешь остановиться и обратиться за помощью, сохраняя личные сведения."},
};
